 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width color bars encode a cyclic row sequence: each bar's row
    # residue gives the color for that position in the cycle.
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] != 0 and all(v == row[0] for v in row)]
    if bars:
        period = len(bars)
        seq = {r % period: color for r, color in bars}
        return [[seq[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal strokes encode a cyclic pattern by the diagonal residue c-r.
    # The motifs in this task use a five-cell diagonal cycle.
    period = 5
    colors = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                residue = (c - r) % period
                colors[residue] = value
    return [[colors.get((c - r) % period, 0) for c in range(w)]
            for r in range(h)]


if __name__ == '__main__':
    # Validate both demonstrations' encoded periodic patterns.
    demo1 = [[0] * 26 for _ in range(26)]
    for r, color in [(3, 5), (9, 5), (13, 7), (18, 4), (19, 3), (21, 6), (22, 8)]:
        demo1[r] = [color] * 26
    got1 = transform(demo1)
    assert [row[0] for row in got1[:7]] == [6, 8, 5, 5, 4, 3, 7]

    demo2 = [[0] * 24 for _ in range(24)]
    for r in range(24):
        for c, color in [(r - 5, 3), (r + 6, 5), (r + 8, 7), (r + 22, 9), (r - 16, 5)]:
            if 0 <= c < 24:
                demo2[r][c] = color
    got2 = transform(demo2)
    assert got2[0] == [3, 5, 9, 7, 5] * 4 + [3, 5, 9, 7]
    print('demo pattern assertions passed')
