               (d - p in stripes and stripes[d-p] == colors)
               for d, colors in stripes.items()):
            period = p
            break
    if period is None:
        # The frame depicts a diagonal motif spanning the grid; use the observed
        # colored offsets in their order and cycle through them.
        period = max(offsets) - min(offsets) + 1
        lookup = {d % period: next(iter(colors)) for d, colors in stripes.items()}
        # Keep unobserved residues as the background color.
        return [[lookup.get((c-r-min(offsets)) % period, 0) for c in range(w)]
                for r in range(h)]
    lookup = {d % period: next(iter(colors)) for d, colors in stripes.items()}
    return [[lookup.get((c-r) % period, 0) for c in range(w)] for r in range(h)]


