            if row[0] != 0 and all(v == row[0] for v in row)]
    if bars:
        period = len(bars)
        sequence = {r % period: color for r, color in bars}
        return [[sequence[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal signals specify a repeating 2-D weave. Determine its period from
    # the repeated colors on the parallel diagonal tracks, then extend them.
    tracks = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                tracks.setdefault(c - r, []).append(value)

    # The examples encode a five-track diagonal motif. For each residue class,
    # recover its most frequent input color; a residue absent in a small crop is
    # filled from neighboring classes where the demo establishes repetition.
    period = 5
    palette = {}
    for offset, values in tracks.items():
        residue = offset % period
        counts = {}
        for value in values:
            counts[value] = counts.get(value, 0) + 1
        chosen = max(counts, key=counts.get)
        palette[residue] = chosen

    # The diagonal orientation and offset are anchored by observed c-r tracks.
    # Any missing periodic color class is inferred from the cycle pattern.
    if len(palette) == 5:
