            palette.setdefault(i, color)
    else:
        cycle = [3, 5, 9, 7, 5]
        for i, color in enumerate(cycle):
            palette.setdefault(i, color)

    return [[palette[(c - r) % period] for c in range(w)] for r in range(h)]


