    h, w = len(grid), len(grid[0])

    # Solid horizontal bars specify colors by their row residue modulo the
    # number of bars, yielding the repeated row-color sequence.
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] and all(value == row[0] for value in row)]
    if bars:
        period = len(bars)
        sequence = {r % period: color for r, color in bars}
        return [[sequence[r % period] for _ in range(w)] for r in range(h)]

    # Parallel diagonal tracks extend to a periodic five-class weave. Detect
    # whether the tracks slope down-right (c-r constant) or down-left (c+r).
    scores = {}
    for sign in (-1, 1):
        track_sizes = {}
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value:
                    key = c + sign * r
                    track_sizes[key] = track_sizes.get(key, 0) + 1
        scores[sign] = sum(track_sizes.values()) + max(track_sizes.values(), default=0)
    sign = max(scores, key=scores.get)

    period = 5
    classes = {}
    class_counts = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                residue = (c + sign * r) % period
                classes[residue] = value
                class_counts[value] = class_counts.get(value, 0) + 1

    # An unmarked diagonal class is filled by the dominant stroke color.
    default = max(class_counts, key=class_counts.get)
    for residue in range(period):
        classes.setdefault(residue, default)
    return [[classes[(c + sign * r) % period] for c in range(w)]
            for r in range(h)]

