    h, w = len(grid), len(grid[0])
    # In full-row examples, stripe colors repeat by row index modulo count.
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] and all(v == row[0] for v in row)]
    if bars:
        period = len(bars)
        colors = {r % period: v for r, v in bars}
        return [[colors[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal traces specify a five-color periodic grid on their parallel
    # diagonal residue classes. Choose the slope shared by the long tracks.
    groups = {}
    for sign in (-1, 1):
        counts = {}
        for r, row in enumerate(grid):
            for c, v in enumerate(row):
                if v:
                    intercept = c + sign * r
                    counts.setdefault(intercept, []).append(v)
        groups[sign] = counts
    # A track with constant c-r means sign=-1. Count same-color continuity.
    score = {s: sum(len(vals) ** 2 for vals in groups[s].values()) for s in groups}
