    # The demos show color 3 may span the unmarked class adjoining a double
    # width diagonal; otherwise the marked tracks completely identify palette.
    for k in range(5):
        if k not in palette:
            palette[k] = 3
    return [[palette[(c + sign * r) % 5] for c in range(w)] for r in range(h)]

