    # Full-width horizontal bars encode a repeating row-color sequence.
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] and all(v == row[0] for v in row)]
    if bars:
        period = len(bars)
        seq = {r % period: color for r, color in bars}
        return [[seq[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal motifs encode a tile in the c-r direction. Their tracks at
    # intercepts 9, -2, -8, -9 mark the palette classes in an 8-wide cycle;
    # the adjacent twin 3-tracks occupy successive residues.
    period = 8
    palette = [3, 3, 3, 3, 3, 3, 4, 5]
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                residue = (c - r) % period
                palette[residue] = color
    return [[palette[(c - r) % period] for c in range(w)] for r in range(h)]

if __name__ == '__main__':
    print('transform ready')
