 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width bars encode a periodic row sequence. Find the shortest
    # modulus that does not assign different colors to the same row class.
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] and all(v == row[0] for v in row)]
    if bars:
        period = None
        for p in range(1, max(h, w) + 1):
            by_residue = {}
            if all((r % p not in by_residue or by_residue[r % p] == color)
                   and not by_residue.setdefault(r % p, color) != color
                   for r, color in bars):
                period = p
                break
        if period is None:
            period = max(r for r, _ in bars) + 1
        palette = {}
